import json
import os
import time
import uuid
from typing import Any, Dict, Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


def write_json_log_event(
    message: str,
    level: str = "INFO",
    logger_name: str = "managed-log-writer",
    log_group_name: str = "/application/structured-json",
    log_stream_name: Optional[str] = None,
    extra_fields: Optional[Dict[str, Any]] = None,
    region_name: Optional[str] = None,
) -> Dict[str, Any]:
    """
    Write a structured JSON log event to Amazon CloudWatch Logs.

    Requires AWS credentials to be configured via standard boto3 mechanisms,
    such as AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY, and AWS_REGION.
    """
    region_name = region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION") or "us-east-1"
    log_stream_name = log_stream_name or f"{logger_name}-{uuid.uuid4().hex[:12]}"

    client = boto3.client("logs", region_name=region_name)

    try:
        try:
            client.create_log_group(logGroupName=log_group_name)
        except ClientError as e:
            if e.response.get("Error", {}).get("Code") != "ResourceAlreadyExistsException":
                raise

        try:
            client.create_log_stream(logGroupName=log_group_name, logStreamName=log_stream_name)
        except ClientError as e:
            if e.response.get("Error", {}).get("Code") != "ResourceAlreadyExistsException":
                raise

        event: Dict[str, Any] = {
            "timestamp": int(time.time() * 1000),
            "level": level,
            "logger": logger_name,
            "message": message,
        }
        if extra_fields:
            event.update(extra_fields)

        response = client.put_log_events(
            logGroupName=log_group_name,
            logStreamName=log_stream_name,
            logEvents=[
                {
                    "timestamp": event["timestamp"],
                    "message": json.dumps(event, separators=(",", ":"), ensure_ascii=False),
                }
            ],
        )

        return {
            "log_group_name": log_group_name,
            "log_stream_name": log_stream_name,
            "sequence_token": response.get("nextSequenceToken"),
            "event": event,
        }

    except (BotoCoreError, ClientError) as exc:
        raise RuntimeError(f"Failed to write log event to CloudWatch Logs: {exc}") from exc
